class LRUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.data = {}
        self.order = []

    def get(self, key):
        if key not in self.data:
            return None
        # Move to the end (most recently used)
        self.order.remove(key)
        self.order.append(key)
        return self.data[key]

    def put(self, key, value):
        if key in self.data:
            # Key exists, remove from order and add back at the end
            self.order.remove(key)
            self.order.append(key)
            self.data[key] = value
        else:
            # New key, insert it at the beginning (oldest first)
            self.order.insert(0, key)
            self.data[key] = value

    def __len__(self):
        return len(self.data)
